// The path explorer (doc 15 §6.1, WFD-34): every distinct path the core enumerates (retry loops at 0, 1 and max), the
// statechart edges they cover, and specs for the chosen ones, generated by the local host into the owner's test project.
import type { PathsResult, WorkflowPath } from '@sourceflow/core-client';
import { useMemo, useState } from 'react';
import type { ServiceDto, SpecsResult } from '../api.ts';
import { usePaths, useServices } from '../services.tsx';

interface Props {
  path: string;
  text: string;
  name: string;
  owner: ServiceDto | undefined;
  readOnly: boolean;
  /** Unsaved changes: the host generates specs from the saved file. */
  dirty: boolean;
  selected: readonly string[] | undefined;
  onSelect: (paths: string[]) => void;
  onSimulate: (path: WorkflowPath) => void;
}

type Filter = 'all' | 'cover' | 'Completed' | 'Compensated' | 'ManualIntervention';

const FILTERS: Array<{ value: Filter; label: string }> = [
  { value: 'all', label: 'All paths' },
  { value: 'cover', label: 'The minimal cover' },
  { value: 'Completed', label: 'Paths that complete' },
  { value: 'Compensated', label: 'Paths that compensate' },
  { value: 'ManualIntervention', label: 'Paths that need an operator' },
];

const END_SYMBOL: Record<WorkflowPath['end'], string> = { Completed: '✓', Compensated: '⟲', ManualIntervention: '✋' };

/** The edges a path covers. */
export function edgesOf(path: WorkflowPath): Set<string> {
  return new Set(path.moves.flatMap((m) => (m.retryEdge === undefined ? [m.edge] : [m.edge, m.retryEdge])));
}

/** Which of the coverable edges the chosen paths cover, and which they miss. */
export function coverage(result: PathsResult, chosen: readonly string[]): { covered: string[]; missed: string[]; coverable: string[] } {
  const uncovered = new Set(result.uncovered);
  const coverable = result.edges.filter((e) => !uncovered.has(e));
  const edges = new Set(result.paths.filter((p) => chosen.includes(p.id)).flatMap((p) => [...edgesOf(p)]));
  return { coverable, covered: coverable.filter((e) => edges.has(e)), missed: coverable.filter((e) => !edges.has(e)) };
}

function shown(result: PathsResult, filter: Filter): WorkflowPath[] {
  const cover = new Set(result.minimalCover);
  return result.paths.filter((p) => filter === 'all' || (filter === 'cover' ? cover.has(p.id) : p.end === filter));
}

export function PathExplorer({ path, text, name, owner, readOnly, dirty, selected, onSelect, onSimulate }: Props) {
  const { api } = useServices();
  const paths = usePaths(text);
  const [filter, setFilter] = useState<Filter>('all');
  const [preview, setPreview] = useState<SpecsResult | undefined>();
  const [specsState, setSpecsState] = useState<{ busy?: boolean; message?: string; error?: string }>({});
  const result = paths.data;
  const chosen = useMemo(() => selected ?? result?.minimalCover ?? [], [selected, result]);
  const cover = useMemo(() => new Set(result?.minimalCover ?? []), [result]);

  if (paths.isError) {
    return <p role="alert">The paths need a readable workflow: {(paths.error as Error).message}</p>;
  }

  if (result === undefined) {
    return <p role="status">Enumerating the paths…</p>;
  }

  const total = coverage(result, result.paths.map((p) => p.id));
  const mine = coverage(result, chosen);
  const list = shown(result, filter);
  const toggle = (id: string, on: boolean) => onSelect(on ? [...chosen, id] : chosen.filter((p) => p !== id));

  const specs = async (dryRun: boolean) => {
    if (owner === undefined) {
      return;
    }

    setSpecsState({ busy: true });
    try {
      const done = await api.specs(owner.name, { workflow: path, paths: chosen, dryRun });
      if (dryRun) {
        setPreview(done);
        setSpecsState({ message: `${done.tests} test${done.tests === 1 ? '' : 's'} for ${done.path}.` });
      } else {
        setSpecsState({ message: `Wrote ${done.tests} test${done.tests === 1 ? '' : 's'} to ${done.path}.` });
      }
    } catch (failure) {
      setSpecsState({ error: (failure as Error).message });
    }
  };

  const configured = owner?.tests !== undefined && owner.module !== undefined;
  return (
    <section className="paths" aria-labelledby="paths-title">
      <h2 id="paths-title">Paths</h2>
      <p role="status" className="paths-summary">
        {result.paths.length} paths · {total.covered.length} of {result.edges.length} edges covered · a minimal cover of {result.minimalCover.length}
      </p>
      {result.truncated ? <p className="warning">The enumeration stopped at its limits: some paths aren't listed.</p> : null}
      {result.uncovered.length > 0 ? (
        <details>
          <summary>{result.uncovered.length} edge{result.uncovered.length === 1 ? '' : 's'} no path covers</summary>
          <ul>{result.uncovered.map((e) => <li key={e}><code>{e}</code></li>)}</ul>
        </details>
      ) : null}

      <div className="toolbar wrap">
        <label className="field">
          <span>Show</span>
          <select value={filter} onChange={(e) => setFilter(e.target.value as Filter)}>
            {FILTERS.map((f) => <option key={f.value} value={f.value}>{f.label}</option>)}
          </select>
        </label>
        <button type="button" className="button" onClick={() => onSelect([...result.minimalCover])}>Select the minimal cover</button>
        <button type="button" className="button" onClick={() => onSelect([...new Set([...chosen, ...list.map((p) => p.id)])])}>Select the shown paths</button>
        <button type="button" className="button" onClick={() => onSelect([])}>Clear the selection</button>
      </div>

      <ul className="path-list" aria-label={`Paths of ${name}`}>
        {list.map((p) => (
          <li key={p.id} className={`path end-${p.end}`}>
            <label className="path-head">
              <input type="checkbox" checked={chosen.includes(p.id)} onChange={(e) => toggle(p.id, e.target.checked)} aria-label={`Select ${p.id}`} />
              <strong>{p.id}</strong>
              <span className="path-end">{END_SYMBOL[p.end]} {p.end}</span>
              {cover.has(p.id) ? <span className="path-cover" title="In the minimal cover">★ cover</span> : null}
            </label>
            <p className="path-text">{p.text.slice(p.id.length + 1)}</p>
            <button type="button" className="button" aria-label={`Simulate ${p.id}`} onClick={() => onSimulate(p)}>Simulate</button>
          </li>
        ))}
      </ul>

      <fieldset className="section">
        <legend>Specs</legend>
        <p role="status">
          {chosen.length} path{chosen.length === 1 ? '' : 's'} selected, covering {mine.covered.length} of {mine.coverable.length} edges.
        </p>
        {mine.missed.length > 0 ? (
          <details>
            <summary>Edges the selection misses</summary>
            <ul>{mine.missed.map((e) => <li key={e}><code>{e}</code></li>)}</ul>
          </details>
        ) : null}
        {!configured ? (
          <p className="hint">
            To write specs, give {owner?.name ?? 'the owner'} a <code>tests</code> folder (its test project) and its <code>module</code> type in the workspace file.
          </p>
        ) : (
          <p className="hint">One <code>WorkflowSpec</code> test per path, written to <code>{owner.tests}/Workflows</code> from the saved file.</p>
        )}
        {dirty ? <p className="warning">Save the workflow first: specs are generated from the saved file.</p> : null}
        <div className="toolbar">
          <button type="button" className="button" disabled={specsState.busy === true || dirty || !configured || chosen.length === 0} onClick={() => void specs(true)}>Preview specs</button>
          <button type="button" className="button" disabled={specsState.busy === true || dirty || !configured || readOnly || chosen.length === 0} onClick={() => void specs(false)}>
            Write specs
          </button>
        </div>
        {specsState.error !== undefined ? <p role="alert" className="edit-error">{specsState.error}</p> : null}
        {specsState.message !== undefined ? <p role="status" aria-label="Specs">{specsState.message}</p> : null}
        {preview?.text !== undefined ? <pre className="specs-preview" aria-label="Specs preview" tabIndex={0}>{preview.text}</pre> : null}
      </fieldset>
    </section>
  );
}
